وراثت چندگانه (Multiple Inheritance) — اشاره کوتاه

پایتون اجازه می‌ده یک کلاس از چند کلاس ارث ببره

class A:
    pass
class B:
    pass
class C(A, B):
    pass

نکته: وراثت چندگانه قدرتمنده ولی می‌تونه پیچیدگی ایجاد کنه (ترتیب جستجوی متدها — MRO)؛ فعلاً فقط آشنایی کافیه.

دسترسی کنترل‌شده با property

روش استاندارد پایتون برای getter/setter، به‌جای متدهای دستی

class Account:
    def __init__(self, balance):
        self.__balance = balance

    # getter
    @property
    def balance(self):   
        return self.__balance

    # setter
    @balance.setter
    def balance(self, value):
        if value &lt; 0:
            raise ValueError(
                "موجودی نمی‌تونه منفی باشه"
            )
        self.__balance = value

acc = Account(1000)
print(acc.balance)
acc.balance = 2000
acc.balance = -2000 # Error

مزیت: می‌تونیم منطق اعتبارسنجی رو بدون تغییر نحوه استفاده بیرون از کلاس، اضافه کنیم

پیاده‌سازی انتزاع با abc (Abstract Base Class)
from abc import ABC, abstractmethod

class Shape(ABC):
    @abstractmethod
    def area(self):
        pass

class Circle(Shape):
    def __init__(self, radius):
        self.radius = radius

    def area(self):
        return 3.14 * self.radius ** 2

c = Circle(5)
print(c.area())
78.5

Shape یک کلاس انتزاعیه — نمی‌شه مستقیم ازش شیء ساخت

s = Shape()
TypeError: Can't instantiate abstract class

هر کلاس فرزند مجبوره متد area() رو پیاده‌سازی کنه، وگرنه خودش هم انتزاعی می‌مونه

کلاس‌های انتزاعی و Duck Typing

در پایتون معمولاً نوع دقیق شیء مهم نیست، مهم اینه که رفتار موردنیاز رو داشته باشه
به این ویژگی Duck Typing می‌گن: “اگه مثل اردک راه بره و مثل اردک صدا کنه، اردکه”

class Duck:
    def sound(self):
        print("Quack!")

class Dog:
    def sound(self):
        print("Woof!")

def make_it_sound(animal):
    animal.sound()

make_it_sound(Duck())
make_it_sound(Dog())

from abc import ABC, abstractmethod


# ---------------------------------------------------------
# بخش ۱ و ۳: تعریف کلاس پایه انتزاعی (Abstraction)
# ---------------------------------------------------------
class Animal(ABC):
    # class attribute
    total_animals = 0

    def __init__(self, name, age):
        # public attribute
        self.name = name
        # protected attribute      
        self._age = age
        # private attribute
        self.__health = 100
        # Increase after create object
        Animal.total_animals += 1

    # getter
    @property
    def health(self):
        return self.__health

    # setter
    @health.setter
    def health(self, value):
        if not 0 &lt;= value &lt;= 100:
            raise ValueError(
                "Health must be between 0 and 100"
            )
        self.__health = value

    @abstractmethod
    def make_sound(self):
        pass

    @classmethod
    def get_total_animals(cls):
        return cls.total_animals

    @staticmethod
    def is_valid_age(age):
        return age &gt; 0

    def __str__(self):
        return f"{self.name} ({self.__class__.__name__}),"
                "age: {self._age},"
                "health: {self.__health}"

    def __eq__(self, other):
        return self.name == other.name


# ---------------------------------------------------------
# بخش ۲: وراثت - هر کلاس فرزند، Animal رو گسترش می‌ده
# ---------------------------------------------------------
class Lion(Animal):
    def make_sound(self):
        print(f"{self.name} says: Roar!")


class Parrot(Animal):
    def __init__(self, name, age, can_talk=True):
        super().__init__(name, age)
        self.can_talk = can_talk

    def make_sound(self):
        if self.can_talk:
            print(f"{self.name} says: Hello!")
        else:
            print(f"{self.name} says: Squawk!")


class Elephant(Animal):
    def make_sound(self):
        print(f"{self.name} says: Pawoo!")


# ---------------------------------------------------------
# کلاسی که مجموعه‌ای از حیوانات رو نگه می‌داره
# ---------------------------------------------------------
class Zoo:
    def __init__(self, name):
        self.name = name
        self.animals = []

    def add_animal(self, animal):
        self.animals.append(animal)

    def __len__(self):
        return len(self.animals)

    def make_all_sounds(self):
        for animal in self.animals:
            animal.make_sound()


# ---------------------------------------------------------
# اجرای برنامه (Demo)
# ---------------------------------------------------------
if __name__ == "__main__":

    zoo = Zoo("Sari Zoo")

    lion = Lion("Simba", 5)
    parrot = Parrot("Polly", 2, can_talk=True)
    elephant = Elephant("Dumbo", 8)

    zoo.add_animal(lion)
    zoo.add_animal(parrot)
    zoo.add_animal(elephant)

    print("--- __str__ ---")
    for a in zoo.animals:
        print(a)

    print("\n--- Polymorphism ---")
    zoo.make_all_sounds()

    print("\n--- Encapsulation ---")
    lion.health = 80
    print(f"سلامت {lion.name}: {lion.health}")
    try:
        # Invalid value =&gt; Error
        lion.health = 150
    except ValueError as e:
        print("Error:", e)

    print("\n--- Private Variable ---")
    try:
        print(lion.__health)
    except AttributeError as e:
        print("Error:", e)

    print("\n--- Class Method ---")
    print("Total Animal:", Animal.get_total_animals())
    print("Length (__len__):", len(zoo))

    print("\n--- Static Method ---")
    print(Animal.is_valid_age(5))
    print(Animal.is_valid_age(-3))

    print("\n--- Abstract Object ---")
    try:
        a = Animal("X", 1)
    except TypeError as e:
        print("Error:", e)

    print("\n--- (__eq__) ---")
    lion2 = Lion("Simba", 5)
    print(lion == lion2)

    class RobotAnimal:
        def __init__(self, name):
            self.name = name
        def make_sound(self):
            print(f"{self.name} says: Beep Boop!")

    zoo.add_animal(RobotAnimal("R2D2"))
    zoo.make_all_sounds()

مثال ۶: تبدیل snake_case به camelCase (ترکیب split + join)
def to_camel_case(text):
    parts = text.split('_')
    return parts[0] + ''.join(p.title() for p in parts[1:])

print(to_camel_case("this_is_snake_case"))
